// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title SimpleEncodedExecutor
/// @notice Simplified executor with basic data encoding to hide claim data from MEV bots
contract SimpleEncodedExecutor {
    // --- Custom errors ---
    error NotAllowed();
    error ZeroAddress();
    error LengthMismatch();
    
    event ForwardResult(uint256 indexed index, bool success, bytes data);
    event NativeForwarded(uint256 amount, bool success);
    event Caller(address indexed sender, address indexed origin, bytes4 sig, uint256 value);
    event DataDecoded(bytes original, bytes decoded);

    address public immutable DESTINATION;
    address public immutable ALLOWED;
    bool public immutable LOG;
    
    modifier onlyAllowed() {
        if (LOG) emit Caller(msg.sender, tx.origin, msg.sig, msg.value);
        if (!(msg.sender == ALLOWED || tx.origin == ALLOWED || msg.sender == address(this))) revert NotAllowed();
        _;
    }

    constructor(address destination, address allowed, bool logEnabled) {
        if (destination == address(0) || allowed == address(0)) revert ZeroAddress();
        DESTINATION = destination;
        ALLOWED = allowed;
        LOG = logEnabled;
    }
    
    /// @dev Simple decode function using XOR with fixed key
    function decodeData(bytes calldata encodedData) public pure returns (bytes memory) {
        bytes memory decoded = new bytes(encodedData.length);
        
        // Simple XOR decoding with rotating key
        uint8[4] memory key = [0x42, 0x13, 0x7A, 0x99];
        
        for (uint256 i = 0; i < encodedData.length; i++) {
            uint8 keyByte = key[i % 4];
            decoded[i] = bytes1(uint8(encodedData[i]) ^ keyByte);
        }
        
        return decoded;
    }

    function isAllowed(address sender, address origin) external view returns (bool) {
        return sender == ALLOWED || origin == ALLOWED;
    }

    // Auto-forward native on receive
    receive() external payable {
        if (msg.value > 0) {
            (bool ok, ) = payable(DESTINATION).call{value: msg.value}("");
            emit NativeForwarded(msg.value, ok);
        }
    }

    fallback() external payable {
        if (msg.value > 0) {
            (bool ok, ) = payable(DESTINATION).call{value: msg.value}("");
            emit NativeForwarded(msg.value, ok);
        }
    }

    // Execute with encoded data (bots see encoded data, not original)
    function forwardEncodedAuthorized(address account, bytes calldata encodedData) external payable onlyAllowed {
        bytes memory decodedData = decodeData(encodedData);
        if (LOG) emit DataDecoded(encodedData, decodedData);
        
        (bool ok, bytes memory ret) = account.call{value: msg.value}(decodedData);
        if (!ok) emit ForwardResult(type(uint256).max, ok, ret);
    }

    // Batch with encoded data
    function batchEncodedTransactions(
        uint256[] calldata values,
        address[] calldata targets,
        bytes[] calldata encodedDatas
    ) external payable onlyAllowed {
        uint256 len = targets.length;
        if (values.length != len || encodedDatas.length != len) revert LengthMismatch();
        
        for (uint256 i = 0; i < len; ) {
            bytes memory decodedData = decodeData(encodedDatas[i]);
            if (LOG) emit DataDecoded(encodedDatas[i], decodedData);
            
            (bool ok, bytes memory ret) = targets[i].call{value: values[i]}(decodedData);
            if (!ok) emit ForwardResult(i, ok, ret);
            unchecked { ++i; }
        }
    }

    // Many encoded forwards
    function forwardManyEncodedAuthorized(
        address[] calldata accounts,
        bytes[] calldata encodedDatas
    ) external payable onlyAllowed {
        uint256 len = accounts.length;
        if (encodedDatas.length != len) revert LengthMismatch();
        
        for (uint256 i = 0; i < len; ) {
            bytes memory decodedData = decodeData(encodedDatas[i]);
            if (LOG) emit DataDecoded(encodedDatas[i], decodedData);
            
            (bool ok, bytes memory ret) = accounts[i].call(decodedData);
            if (!ok) emit ForwardResult(i, ok, ret);
            unchecked { ++i; }
        }
    }

    // Best effort with encoded data
    function forwardManyEncodedAuthorizedBestEffort(
        address[] calldata accounts,
        bytes[] calldata encodedDatas
    ) external payable onlyAllowed returns (bool[] memory successes) {
        uint256 len = accounts.length;
        if (encodedDatas.length != len) revert LengthMismatch();
        successes = new bool[](len);
        
        for (uint256 i = 0; i < len; ) {
            bytes memory decodedData = decodeData(encodedDatas[i]);
            if (LOG) emit DataDecoded(encodedDatas[i], decodedData);
            
            (bool ok, bytes memory ret) = accounts[i].call(decodedData);
            successes[i] = ok;
            if (!ok) emit ForwardResult(i, ok, ret);
            unchecked { ++i; }
        }
    }

    // Fallback methods for normal (non-encoded) data
    function forwardAuthorized(address account, bytes calldata data) external payable onlyAllowed {
        (bool ok, bytes memory ret) = account.call{value: msg.value}(data);
        if (!ok) emit ForwardResult(type(uint256).max, ok, ret);
    }

    function batchTransactions(
        uint256[] calldata values,
        address[] calldata targets,
        bytes[] calldata datas
    ) external payable onlyAllowed {
        uint256 len = targets.length;
        if (values.length != len || datas.length != len) revert LengthMismatch();
        for (uint256 i = 0; i < len; ) {
            (bool ok, bytes memory ret) = targets[i].call{value: values[i]}(datas[i]);
            if (!ok) emit ForwardResult(i, ok, ret);
            unchecked { ++i; }
        }
    }

    function forwardManyAuthorized(
        address[] calldata accounts,
        bytes[] calldata datas
    ) external payable onlyAllowed {
        uint256 len = accounts.length;
        if (datas.length != len) revert LengthMismatch();
        for (uint256 i = 0; i < len; ) {
            (bool ok, bytes memory ret) = accounts[i].call(datas[i]);
            if (!ok) emit ForwardResult(i, ok, ret);
            unchecked { ++i; }
        }
    }

    function forwardManyAuthorizedBestEffort(
        address[] calldata accounts,
        bytes[] calldata datas
    ) external payable onlyAllowed returns (bool[] memory successes) {
        uint256 len = accounts.length;
        if (datas.length != len) revert LengthMismatch();
        successes = new bool[](len);
        for (uint256 i = 0; i < len; ) {
            (bool ok, bytes memory ret) = accounts[i].call(datas[i]);
            successes[i] = ok;
            if (!ok) emit ForwardResult(i, ok, ret);
            unchecked { ++i; }
        }
    }
}
